  if(flow>0){const op=(.5+.5*Math.min(1,flow/cap)).toFixed(2);s+=h?`<rect x="${X+2}" y="${y1-th/2+2}" width="${L-4}" height="${th-4}" rx="${(th-4)/2}" fill="url(#pgW)" opacity="${op}"/>`:`<rect x="${x1-th/2+2}" y="${Y+2}" width="${th-4}" height="${L-4}" rx="${(th-4)/2}" fill="url(#pgWV)" opacity="${op}"/>`;
   const n=Math.max(2,Math.round(flow*L/40)),dur=(L/75).toFixed(2),a=h?(rev?x2:x1):(rev?y2:y1),b=h?(rev?x1:x2):(rev?y1:y2);
   for(let k=0;k<n;k++){const off=(((k*37)%100)/100-.5)*(th-9),bg=(k/n*dur).toFixed(2),r=(1.3+((k*13)%10)/8).toFixed(1);s+=h?`<circle cy="${(y1+off).toFixed(1)}" r="${r}" fill="#fff" opacity=".85"><animate attributeName="cx" from="${a}" to="${b}" dur="${dur}s" begin="-${bg}s" repeatCount="indefinite"/></circle>`:`<circle cx="${(x1+off).toFixed(1)}" r="${r}" fill="#fff" opacity=".85"><animate attributeName="cy" from="${a}" to="${b}" dur="${dur}s" begin="-${bg}s" repeatCount="indefinite"/></circle>`}}
  if(h)s+=`<line x1="${X+th/2}" y1="${y1-th/2+3}" x2="${X+L-th/2}" y2="${y1-th/2+3}" stroke="#fff" stroke-width="2" opacity=".85" stroke-linecap="round"/>`;
