 flange(x,y,th,v){return v?`<rect x="${x-th/2-4}" y="${y-5}" width="${th+8}" height="10" rx="2" fill="url(#pgM)"/>`:`<rect x="${x-5}" y="${y-th/2-4}" width="10" height="${th+8}" rx="2" fill="url(#pgMV)"/>`},
