/* ---------- aplikasi ---------- */
const PC=['#FF6F59','#13B5A6','#3D8BE0','#F5A623','#8E6BD8','#F2708A','#0E8F86','#FF9F43','#3FA34D','#1F7FA6'];
const KEY='ekspedisi-laut-dalam-v1';
let st={cur:0,ans:{}};
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.ans)st=s}catch(e){}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(st))}catch(e){}};
const app=document.getElementById('app'),map=document.getElementById('map');
const stOf=i=>st.ans[i]===undefined?'':(st.ans[i]===Q[i].jawab?'ok':'bad');
const score=()=>Q.filter((_,i)=>stOf(i)==='ok').length;
const opsiOf=q=>typeof q.opsi==='function'?q.opsi():q.opsi;

function renderTop(){
  document.getElementById('score').innerHTML=`<small>Mutiara</small><b>${score()}</b><small>dari ${Q.length}</small>`;{const dp=document.getElementById('depth');if(dp)dp.innerHTML=`<svg viewBox="0 0 24 24" width="22" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="none" stroke="#BDEFE8" stroke-width="2"/><path d="M12 12 L${(12+7*Math.sin(Math.min(st.cur,19)/19*4.2-2.1)).toFixed(1)} ${(12-7*Math.cos(Math.min(st.cur,19)/19*4.2-2.1)).toFixed(1)}" stroke="#FFD86B" stroke-width="2.4" stroke-linecap="round"/></svg><span><small>Kedalaman</small><b>${Math.min(st.cur+1,20)*25} m</b></span>`}
  map.innerHTML=Q.map((q,i)=>{const s=stOf(i);return `<button class="pl ${s} ${i===st.cur?'cur':''}" style="--c:${PC[i%10]};animation-delay:-${(i*.37)%3}s" data-i="${i}" title="Soal ${i+1}: ${q.judul}" aria-label="Soal ${i+1}${s==='ok'?', benar':s==='bad'?', belum tepat':''}">${i+1}${s?`<span class="mk" style="background:${s==='ok'?'#1C9A5B':'#DD4343'};color:#fff">${s==='ok'?'✓':'✕'}</span>`:''}</button>`}).join('');
  map.querySelectorAll('.pl').forEach(b=>b.onclick=()=>go(+b.dataset.i));
}
function go(i){st.cur=i;save();render();window.scrollTo({top:document.querySelector('main').offsetTop-8,behavior:RM?'auto':'smooth'})}

function render(){
  players.forEach(p=>p.stop());players=[];
  renderTop();
  if(st.cur>=Q.length)return renderSummary();
  const i=st.cur,q=Q[i],opsi=opsiOf(q);
  app.innerHTML=`<article class="card"><div class="flyby" aria-hidden="true"><svg viewBox="-32 -24 64 48" width="64">${fish(0,0,'#FF9F43',1.3)}</svg></div>
    <div class="top"><span class="mno">Soal ${i+1} dari ${Q.length}</span><span class="tag">${q.konsep}</span><span class="tag ${q.tingkat}">${q.tingkat}</span></div>
    <h2 class="ti ${TV[i%4]}" aria-label="${q.judul}">${splitTitle(q.judul)}</h2>
    <div class="talk">${captain}<div class="bubble"><div class="who">Profesor Lina</div><p>${q.cerita}</p></div></div>
    <div class="rules"><h3>Aturan main</h3><ul>${q.aturan.map(a=>`<li><span>${a}</span></li>`).join('')}</ul></div>
    ${stepperHTML('demo','Lihat contoh dulu')}
    <div><div class="lb tm" style="font-weight:900;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:6px">Gambar soal</div><div class="stage" style="border:2px solid var(--line)">${q.visual()}</div></div>
    <div class="ask"><div class="lb">Pertanyaanmu</div><p>${q.tanya}</p></div>
    <div class="opts" role="radiogroup" aria-label="Pilihan jawaban">${opsi.map((o,k)=>`<button class="opt" data-k="${k}" role="radio" aria-checked="false"><span class="let">${'ABCD'[k]}</span><span class="oc">${o}</span></button>`).join('')}</div>
    <div><button id="cek" class="btn go" disabled>Periksa jawaban</button></div>
    <section id="fb" class="fb" hidden></section>
  </article>
  <div class="nav"><button id="prev" class="btn" ${i===0?'disabled':''}>← Soal sebelumnya</button><button id="next" class="btn">${i===Q.length-1?'Lihat hasil':'Soal berikutnya →'}</button></div>`;
  stepper($(app,'#demo'),q.demo(),false);
  const opts=[...app.querySelectorAll('.opt')],cek=$(app,'#cek');let sel=null;
  opts.forEach(b=>b.onclick=()=>{sel=+b.dataset.k;sfx('pick');b.animate([{transform:'scale(1)'},{transform:'scale(1.05)'},{transform:'none'}],{duration:260});opts.forEach(o=>{const on=o===b;o.classList.toggle('sel',on);o.setAttribute('aria-checked',on)});cek.disabled=false});
  cek.onclick=()=>{if(sel===null)return;st.ans[i]=sel;save();renderTop();show(true)};
  $(app,'#prev').onclick=()=>go(i-1);$(app,'#next').onclick=()=>go(i+1);
  if(st.ans[i]!==undefined)show(false);
  function show(fresh){
    const p=st.ans[i],ok=p===q.jawab;
    opts.forEach((o,k)=>{o.disabled=true;o.classList.remove('sel');if(k===q.jawab)o.classList.add('right');else if(k===p)o.classList.add('wrong')});
    cek.parentElement.hidden=true;
    const fb=$(app,'#fb');fb.hidden=false;
    fb.innerHTML=`<div class="verdict ${ok?'ok':'bad'}">${ok?`<svg viewBox="0 0 40 40" width="46" class="dance"><polygon points="${starPts(20,21,19,8)}" fill="#FFC93C" stroke="#B88400" stroke-width="1.5"/></svg>`:'<svg viewBox="-26 -28 52 62" width="44" class="shake">'+octo(0,0)+'</svg>'}<div><strong>${ok?'Hebat! Kamu dapat 1 mutiara.':'Hampir! Yuk, tonton pembahasannya.'}</strong><span>Jawaban yang benar adalah <b>${'ABCD'[q.jawab]}</b>.</span></div></div>
      ${stepperHTML('sol','Tonton pembahasan',1)}
      <div class="why"><h3>Kenapa ini penting?</h3><p>${q.info}</p><p class="kk"><b>Kata kunci:</b> ${q.kunci}</p></div>`;
    stepper($(fb,'#sol'),q.bahas(),fresh);
    if(fresh){sfx(ok?'ok':'bad');if(ok)confetti($(fb,'.verdict'))}
    if(fresh)fb.scrollIntoView({behavior:RM?'auto':'smooth',block:'start'});
  }
}

function renderSummary(){
  const n=Object.keys(st.ans).length,s=score();
  const msg=n<Q.length?`Kamu sudah menyelesaikan ${n} dari ${Q.length} soal. Ketuk gelembung bernomor yang belum dibuka.`:s>=17?'Hebat! Kamu siap menjadi penjelajah laut dalam!':s>=11?'Bagus! Ulangi soal yang belum berhasil dan tonton pembahasannya.':'Perjalanan baru dimulai. Tonton contoh di setiap soal pelan-pelan, lalu coba lagi.';
  app.innerHTML=`<section class="sum"><div class="kick" style="color:var(--rocket)">Laporan ekspedisi</div><div class="big">${s}<span style="font-size:.4em;color:var(--muted)"> / ${Q.length} mutiara</span></div><p style="margin:0;font-weight:800;max-width:60ch">${msg}</p>
    <div class="slist">${Q.map((q,i)=>{const t=stOf(i);return `<button class="si" data-i="${i}"><i style="background:${t==='ok'?'var(--ok)':t==='bad'?'var(--bad)':'var(--muted)'}">${t==='ok'?'✓':t==='bad'?'✕':'–'}</i>${i+1}. ${q.judul}</button>`}).join('')}</div>
    <div><button class="btn go" id="again">Mulai lagi dari awal</button></div></section>`;
  app.querySelectorAll('.si').forEach(b=>b.onclick=()=>go(+b.dataset.i));
  $(app,'#again').onclick=()=>{st={cur:0,ans:{}};save();go(0)};
}
if(RM){const sc=document.querySelector('.scene');sc&&sc.pauseAnimations&&sc.pauseAnimations()}const sb=document.getElementById('snd');sb.onclick=()=>{setSnd(!SND);if(SND)sfx('ok')};setSnd(SND);
render();
